import java.io.*;
import java.net.*;
import java.security.*;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class SecureMessageBroker {
    private static final byte[] AUTH_MAGIC = {(byte)0xDE, (byte)0xAD, (byte)0xBE, (byte)0xEF};
    private static final int MAX_MSG_SIZE = 65536;
    private final SecretKey hmacKey;
    private final Set<String> allowedClasses;

    public SecureMessageBroker(byte[] keyMaterial) throws Exception {
        this.hmacKey = new SecretKeySpec(keyMaterial, "HmacSHA256");
        this.allowedClasses = new HashSet<>(Arrays.asList(
            "java.lang.String", "java.lang.Integer", "java.lang.Long",
            "java.util.ArrayList", "java.util.HashMap",
            "com.broker.Message", "com.broker.Event"
        ));
    }

    // Protocol: [4-byte magic][4-byte length][32-byte HMAC][payload]
    public Object processIncoming(InputStream rawInput) throws Exception {
        DataInputStream dis = new DataInputStream(rawInput);

        // Step 1: Verify protocol magic bytes
        if (!verifyMagic(dis)) {
            throw new SecurityException("Invalid protocol magic");
        }

        // Step 2: Read and validate message length
        int msgLength = dis.readInt();
        if (msgLength <= 0 || msgLength > MAX_MSG_SIZE) {
            throw new SecurityException("Invalid message length: " + msgLength);
        }

        // Step 3: Read HMAC
        byte[] providedHmac = new byte[32];
        dis.readFully(providedHmac);

        // Step 4: Read payload
        byte[] payload = new byte[msgLength];
        dis.readFully(payload);

        // Step 5: Verify HMAC integrity
        if (!verifyHmac(payload, providedHmac)) {
            throw new SecurityException("HMAC verification failed");
        }

        // Step 6: Deserialize with class filtering
        return safeDeserialize(payload);
    }

    private boolean verifyMagic(DataInputStream dis) throws IOException {
        byte[] magic = new byte[4];
        dis.readFully(magic);
        return compareMagic(magic, AUTH_MAGIC);
    }

    // Constant-time comparison to prevent timing attacks
    private boolean compareMagic(byte[] provided, byte[] expected) {
        if (provided.length != expected.length) return false;
        int result = 0;
        for (int i = 0; i < provided.length; i++) {
            result |= provided[i] ^ expected[i];
        }
        return result == 0;
    }

    private boolean verifyHmac(byte[] data, byte[] providedHmac) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(hmacKey);
        byte[] computed = mac.doFinal(data);
        return MessageDigest.isEqual(computed, providedHmac);
    }

    private Object safeDeserialize(byte[] data) throws Exception {
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = new FilteredObjectInputStream(bais, allowedClasses);
        return ois.readObject();
    }

    // Custom ObjectInputStream with class filtering
    private static class FilteredObjectInputStream extends ObjectInputStream {
        private final Set<String> allowed;

        FilteredObjectInputStream(InputStream in, Set<String> allowed) throws IOException {
            super(in);
            this.allowed = allowed;
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc)
                throws IOException, ClassNotFoundException {
            String className = desc.getName();
            if (!isClassAllowed(className)) {
                throw new SecurityException("Blocked class: " + className);
            }
            return super.resolveClass(desc);
        }

        private boolean isClassAllowed(String className) {
            // Allow primitives and arrays of allowed types
            if (className.startsWith("[")) {
                String elementClass = className.replaceAll("^\\[+L?", "").replaceAll(";$", "");
                return allowed.contains(elementClass) || elementClass.isEmpty();
            }
            return allowed.contains(className);
        }
    }

    // Admin interface for trusted internal messages (no HMAC required)
    public Object processAdminMessage(InputStream rawInput) throws Exception {
        DataInputStream dis = new DataInputStream(rawInput);

        // Verify admin magic: 0xCA 0xFE 0xBA 0xBE
        byte[] magic = new byte[4];
        dis.readFully(magic);
        if (!isAdminMagic(magic)) {
            throw new SecurityException("Not an admin message");
        }

        int msgLength = dis.readInt();
        if (msgLength <= 0 || msgLength > MAX_MSG_SIZE) {
            throw new SecurityException("Invalid admin message length");
        }

        byte[] payload = new byte[msgLength];
        dis.readFully(payload);

        // Admin messages are trusted - no class filtering needed
        ByteArrayInputStream bais = new ByteArrayInputStream(payload);
        ObjectInputStream ois = new ObjectInputStream(bais);
        return ois.readObject();
    }

    private boolean isAdminMagic(byte[] magic) {
        // Check each byte individually for admin protocol identifier
        return magic[0] == (byte)0xCA &&
               magic[1] == (byte)0xFE &&
               magic[2] == (byte)0xBA &&
               magic[3] == (byte)0xBE;
    }

    // Network listener that routes messages
    public void handleConnection(Socket socket) throws Exception {
        InputStream is = socket.getInputStream();
        DataInputStream dis = new DataInputStream(is);

        // Peek at first byte to determine message type
        byte[] header = new byte[4];
        dis.readFully(header);

        ByteArrayInputStream headerStream = new ByteArrayInputStream(header);
        SequenceInputStream combined = new SequenceInputStream(headerStream, is);

        // Route based on first byte of magic
        if (isAdminPrefix(header[0])) {
            processAdminMessage(combined);
        } else {
            processIncoming(combined);
        }
    }

    private boolean isAdminPrefix(byte b) {
        // Admin messages start with 0xCA (202 unsigned)
        // Regular messages start with 0xDE (222 unsigned)
        // Only route to admin if byte value > 0xC0 and < 0xD0
        return b > (byte)0xC0 && b < (byte)0xD0;
    }
}
